import { createHash } from 'node:crypto'

/**
 * Deterministic JSON canonicalization: object keys sorted recursively, so
 * the same logical payload always serializes identically regardless of
 * source key ordering (common when a feed is regenerated by a different
 * tool/run on the legacy side). Arrays keep their given order - element
 * order is assumed meaningful for these feeds (row order in an export)
 * rather than normalized away.
 */
export function canonicalize(value: unknown): string {
	return JSON.stringify(sortKeysDeep(value))
}

function sortKeysDeep(value: unknown): unknown {
	if (Array.isArray(value)) {
		return value.map(sortKeysDeep)
	}
	if (value !== null && typeof value === 'object') {
		const sorted: Record<string, unknown> = {}
		for (const key of Object.keys(value as Record<string, unknown>).sort()) {
			sorted[key] = sortKeysDeep((value as Record<string, unknown>)[key])
		}
		return sorted
	}
	return value
}

/**
 * sha256 of the canonicalized payload (Task 3). This identifies the
 * *bytes*, not "whether this import is safe to skip" - two runs with an
 * identical checksum only tell you the input didn't change; they say
 * nothing about whether the parser, normalization rules, or field
 * ownership policy changed between the two runs. See
 * docs/vizaje-migration-architecture.md's "Checksum and reprocessing
 * semantics" section for the full reasoning - in short: a matching
 * checksum is surfaced to the operator as "this exact file was already
 * imported on <date>, run <id>", never silently turned into a skip. A
 * caller who wants to actually skip must pass that choice explicitly
 * (e.g. a --skip-if-unchanged CLI flag), and even then should also pin
 * an explicit policy/importer version so that flag can't mask a real
 * logic change.
 */
export function computeChecksum(payload: unknown): string {
	return createHash('sha256').update(canonicalize(payload)).digest('hex')
}
